for _ in range(int(input())):
	n = int(input())
	a = list(map(int, input().split()))
	for i in range(n):
		a.append(a[i])
	r = 0
	for i in range(2 * n):
		r = r ^ a[i]
		a[i] = r
	d = {}
	for i in range(n):
		if a[i] in d:
			d[a[i]] += 1
		else:
			d[a[i]] = 1
	res = len(d)
	for i in range(n, 2 * n):
		if a[i] in d:
			d[a[i]] += 1
		else:
			d[a[i]] = 1
		d[a[i - n]] -= 1
		if d[a[i - n]] == 0:
			del d[a[i - n]]
		res = max(res, len(d))
	print(res)
